const r = await tools.exec_command({cmd:"python3 - <<'PY'
import json,pathlib,collections
r=pathlib.Path('/tmp/objective-recovery-runs/u091/packet/c54-trace')
d=json.loads((r/'timing-trace.json').read_text())
print('predeclared'); p=json.loads((r/'predeclared.json').read_text()); print(json.dumps({k:p[k] for k in ('fixture','source','scope','order','aggregate_workers','gates','stop')},indent=2))
print('trace', {k:d.get(k) for k in ('input_samples','observer_overhead_fraction','absolute_timing_qualification','maximum_numeric_difference','message_numeric_difference','source_verified_unchanged')})
for look in d['looks']:
 print('LOOK',look.keys())
 for k in ('case_id','status','service_seconds','processing_seconds','aggregate_cpu_seconds','average_busy_cores','hardware_utilization_fraction','maximum_numeric_difference'): print(k,look.get(k))
 row=look.get('row',{});print('pipeline',row.get('slot_pipeline'));print('stages',row.get('stages'))
print('event aggregation')
groups=collections.defaultdict(list)
for e in d['events']:
 if e.get('kind')=='phase':groups[e.get('phase')].append(e)
for name,es in sorted(groups.items()):
 dur=[(e['end_ns']-e['start_ns'])/1e9 for e in es]
 cp=sum(e.get('thread_cpu_ns') or 0 for e in es)/1e9
 print(name,'n=',len(es),'sumspan=',round(sum(dur),3),'max=',round(max(dur),3),'sum_thread_cpu=',round(cp,3),'workers=',collections.Counter(e.get('workers') for e in es))
PY",yield_time_ms:10000,max_output_tokens:5500});
